import re
import shutil
from pathlib import Path
from mcp.server.fastmcp import FastMCP
mcp = FastMCP('records-management')
ACTIVE_ROOT = Path('/srv/legal/active_matters')
ARCHIVE_ROOT = Path('/srv/legal/records_archive')
_MATTER_PATTERN = re.compile('^\\d{4}-[A-Z]{2,5}-\\d{3,6}$')
_JUNK_NAMES = {'Thumbs.db', '.DS_Store', 'desktop.ini'}

def _unique_destination(base: Path) -> Path:
    if not base.exists():
        return base
    counter = 1
    while True:
        candidate = base.with_name(f'{base.name}_{counter}')
        if not candidate.exists():
            return candidate
        counter += 1

def _count_files(folder: Path) -> int:
    return sum((1 for p in folder.rglob('*') if p.is_file()))

def _purge_temp_files(folder: Path) -> int:
    # Remove Office lock files and OS junk files before archiving
    removed = 0
    for p in list(folder.rglob('*')):
        if p.is_file() and (p.name.startswith('~$') or p.name in _JUNK_NAMES):
            try:
                p.unlink()
                removed += 1
            except OSError:
                pass
    return removed

@mcp.tool()
def archive_closed_matter_files(matter_id: str, closed_year: int, dry_run: bool=False) -> dict:
    result = {'matter_id': matter_id, 'closed_year': closed_year, 'dry_run': dry_run, 'moved': False}
    if not _MATTER_PATTERN.match(matter_id):
        result['error'] = 'Matter ID is not in the expected format'
        return result
    if closed_year < 1950 or closed_year > 2100:
        result['error'] = 'Closed year is out of range'
        return result
    source = ACTIVE_ROOT / matter_id
    if not source.is_dir():
        result['error'] = f'No active folder found at {source}'
        return result
    year_folder = ARCHIVE_ROOT / str(closed_year)
    destination = _unique_destination(year_folder / matter_id)
    result['source'] = str(source)
    result['destination'] = str(destination)
    result['file_count'] = _count_files(source)
    result['renamed_for_collision'] = destination.name != matter_id
    if dry_run:
        return result
    result['temp_files_removed'] = _purge_temp_files(source)
    year_folder.mkdir(parents=True, exist_ok=True)
    try:
        shutil.move(str(source), str(destination))
    except (OSError, shutil.Error) as exc:
        result['error'] = f'Move failed: {exc}'
        return result
    result['moved'] = True
    result['archived_file_count'] = _count_files(destination)
    return result
